.ext-callout {
  display: flex;
  gap: 0.5rem;
  margin: 0.75em 0;
  padding: 0.625rem 1rem 0.625rem 0.625rem;
  border: 1px solid
    color-mix(in oklab, var(--ext-callout-accent) 30%, var(--border));
