import { useEffect, useRef } from "react";
import type { FocusEvent, PointerEvent } from "react";

export type TooltipSide = "bottom" | "top";

interface TooltipState {
  arrow: HTMLSpanElement;
  frame: number;
  hideTimer: ReturnType<typeof setTimeout> | null;
  label: HTMLSpanElement;
  removeTimer: ReturnType<typeof setTimeout> | null;
  root: HTMLDivElement;
  side: TooltipSide;
  trigger: HTMLElement | null;
}

const TOOLTIP_ID = "ext-tooltip";
const SIDE_OFFSET = 4;
const VIEWPORT_MARGIN = 8;
const ARROW_INSET = 10;
const CLOSE_DELAY = 80;
const EXIT_DURATION = 150;

const ROOT_CLASS =
  "ext-tooltip pointer-events-none fixed top-0 left-0 z-70 inline-flex w-fit max-w-xs items-center gap-1.5 rounded-md bg-foreground px-2 py-1 text-xs text-background [transition:left_150ms_ease-out,top_150ms_ease-out] data-[instant]:transition-none data-[state=closed]:animate-ext-tooltip-out data-[state=open]:animate-ext-tooltip-in";

const ARROW_CLASS =
  "ext-tooltip-arrow absolute size-2.5 -translate-x-1/2 rotate-45 rounded-[2px] bg-foreground";

let state: TooltipState | null = null;

const ensureState = (): TooltipState => {
  if (state?.root.isConnected) {
    return state;
  }
  const root = document.createElement("div");
  root.id = TOOLTIP_ID;
  root.setAttribute("role", "tooltip");
  root.className = ROOT_CLASS;
  const label = document.createElement("span");
  const arrow = document.createElement("span");
  arrow.className = ARROW_CLASS;
  arrow.setAttribute("aria-hidden", "true");
  root.append(label, arrow);
  state = {
    arrow,
    frame: 0,
    hideTimer: null,
    label,
    removeTimer: null,
    root,
    side: "bottom",
    trigger: null,
  };
  return state;
};

const clearTimers = (current: TooltipState) => {
  if (current.hideTimer) {
    clearTimeout(current.hideTimer);
    current.hideTimer = null;
  }
  if (current.removeTimer) {
    clearTimeout(current.removeTimer);
    current.removeTimer = null;
  }
};

const place = (current: TooltipState) => {
  const { arrow, root, trigger } = current;
  if (!trigger) {
    return;
  }
  const rect = trigger.getBoundingClientRect();
  const width = root.offsetWidth;
  const height = root.offsetHeight;
  const below = rect.bottom + SIDE_OFFSET;
  const above = rect.top - SIDE_OFFSET - height;
  const fitsBelow = below + height <= window.innerHeight - VIEWPORT_MARGIN;
  const fitsAbove = above >= VIEWPORT_MARGIN;
  const side: TooltipSide =
    (current.side === "bottom" && (fitsBelow || !fitsAbove)) ||
    (current.side === "top" && !fitsAbove && fitsBelow)
      ? "bottom"
      : "top";
  const center = rect.left + rect.width / 2;
  const left = Math.max(
    VIEWPORT_MARGIN,
    Math.min(center - width / 2, window.innerWidth - width - VIEWPORT_MARGIN)
  );
  root.style.left = `${left}px`;
  root.style.top = `${side === "bottom" ? below : above}px`;
  root.style.transformOrigin = `${center - left}px ${side === "bottom" ? "0" : "100%"}`;
  root.style.setProperty(
    "--ext-slide-y",
    side === "bottom" ? "-0.5rem" : "0.5rem"
  );
  root.dataset.side = side;
  arrow.style.left = `${Math.max(ARROW_INSET, Math.min(center - left, width - ARROW_INSET))}px`;
  arrow.style.top = side === "bottom" ? "-3px" : "";
  arrow.style.bottom = side === "top" ? "-3px" : "";
};

const hideTooltip = () => {
  const current = state;
  if (!current?.trigger) {
    return;
  }
  clearTimers(current);
  cancelAnimationFrame(current.frame);
  current.trigger.removeAttribute("aria-describedby");
  current.trigger = null;
  current.root.dataset.state = "closed";
  current.removeTimer = setTimeout(() => {
    current.removeTimer = null;
    current.root.remove();
  }, EXIT_DURATION);
};

const follow = (current: TooltipState) => {
  cancelAnimationFrame(current.frame);
  const step = () => {
    if (!current.trigger) {
      return;
    }
    if (!current.trigger.isConnected) {
      hideTooltip();
      return;
    }
    place(current);
    current.frame = requestAnimationFrame(step);
  };
  current.frame = requestAnimationFrame(step);
};

const showTooltip = (trigger: HTMLElement, text: string, side: TooltipSide) => {
  const current = ensureState();
  clearTimers(current);
  const reuse =
    current.trigger !== null &&
    current.root.isConnected &&
    current.root.dataset.state === "open";
  if (current.trigger && current.trigger !== trigger) {
    current.trigger.removeAttribute("aria-describedby");
  }
  current.trigger = trigger;
  current.side = side;
  current.label.textContent = text;
  trigger.setAttribute("aria-describedby", TOOLTIP_ID);
  if (!current.root.isConnected) {
    document.body.append(current.root);
  }
  if (reuse) {
    delete current.root.dataset.instant;
  } else {
    current.root.dataset.instant = "";
    current.root.dataset.state = "closed";
    place(current);
    current.root.getBoundingClientRect();
    current.root.dataset.state = "open";
  }
  place(current);
  follow(current);
};

const scheduleHide = () => {
  const current = state;
  if (!current?.trigger) {
    return;
  }
  if (current.hideTimer) {
    clearTimeout(current.hideTimer);
  }
  current.hideTimer = setTimeout(hideTooltip, CLOSE_DELAY);
};

export interface TooltipTriggerHandlers {
  onBlur: (event: FocusEvent<HTMLElement>) => void;
  onFocus: (event: FocusEvent<HTMLElement>) => void;
  onPointerDown: (event: PointerEvent<HTMLElement>) => void;
  onPointerEnter: (event: PointerEvent<HTMLElement>) => void;
  onPointerLeave: (event: PointerEvent<HTMLElement>) => void;
}

export const useTooltip = (
  text: string | undefined,
  side: TooltipSide = "bottom"
): TooltipTriggerHandlers | null => {
  const triggerRef = useRef<HTMLElement | null>(null);

  useEffect(() => {
    const trigger = triggerRef.current;
    if (text && trigger && state?.trigger === trigger) {
      state.label.textContent = text;
    }
  }, [text]);

  useEffect(
    () => () => {
      if (triggerRef.current && state?.trigger === triggerRef.current) {
        hideTooltip();
      }
    },
    []
  );

  if (!text) {
    return null;
  }

  return {
    onBlur: () => {
      hideTooltip();
    },
    onFocus: (event) => {
      if (event.currentTarget.matches(":focus-visible")) {
        triggerRef.current = event.currentTarget;
        showTooltip(event.currentTarget, text, side);
      }
    },
    onPointerDown: () => {
      hideTooltip();
    },
    onPointerEnter: (event) => {
      if (event.pointerType !== "mouse") {
        return;
      }
      triggerRef.current = event.currentTarget;
      showTooltip(event.currentTarget, text, side);
    },
    onPointerLeave: () => {
      scheduleHide();
    },
  };
};

"use client";

import { useCallback, useEffect, useLayoutEffect, useRef } from "react";
import type { CSSProperties, ReactNode, ReactPortal } from "react";
import { createPortal } from "react-dom";

export type FloatingSide = "bottom" | "top" | "left" | "right";
export type FloatingAlign = "start" | "center" | "end";

export interface UseFloatingOptions {
  align?: FloatingAlign;
  onOpenChange?: (open: boolean) => void;
  open: boolean;
  side?: FloatingSide;
  sideOffset?: number;
}

const VIEWPORT_MARGIN = 8;

const SLIDE: Record<FloatingSide, [string, string]> = {
  bottom: ["0", "-0.5rem"],
  left: ["0.5rem", "0"],
  right: ["-0.5rem", "0"],
  top: ["0", "0.5rem"],
};

const fit = (value: number, size: number, limit: number): number =>
  Math.max(VIEWPORT_MARGIN, Math.min(value, limit - size - VIEWPORT_MARGIN));

const alignOn = (
  align: FloatingAlign,
  start: number,
  length: number,
  size: number
): number => {
  if (align === "start") {
    return start;
  }
  if (align === "end") {
    return start + length - size;
  }
  return start + length / 2 - size / 2;
};

const resolveSide = (
  side: FloatingSide,
  rect: DOMRect,
  width: number,
  height: number,
  offset: number
): FloatingSide => {
  const room = {
    bottom: window.innerHeight - rect.bottom - offset - VIEWPORT_MARGIN,
    left: rect.left - offset - VIEWPORT_MARGIN,
    right: window.innerWidth - rect.right - offset - VIEWPORT_MARGIN,
    top: rect.top - offset - VIEWPORT_MARGIN,
  };
  const opposite: Record<FloatingSide, FloatingSide> = {
    bottom: "top",
    left: "right",
    right: "left",
    top: "bottom",
  };
  const need = side === "bottom" || side === "top" ? height : width;
  const flipped = opposite[side];
  return room[side] < need && room[flipped] > room[side] ? flipped : side;
};

export const useFloating = ({
  align = "center",
  onOpenChange,
  open,
  side = "bottom",
  sideOffset = 4,
}: UseFloatingOptions) => {
  const triggerRef = useRef<HTMLElement | null>(null);
  const contentRef = useRef<HTMLDivElement | null>(null);

  const close = useCallback(() => {
    onOpenChange?.(false);
  }, [onOpenChange]);

  const applyPosition = useCallback(() => {
    const trigger = triggerRef.current;
    const content = contentRef.current;
    if (!(trigger instanceof HTMLElement) || !content) {
      return;
    }
    if (!trigger.isConnected) {
      close();
      return;
    }
    const rect = trigger.getBoundingClientRect();
    const width = content.offsetWidth;
    const height = content.offsetHeight;
    const resolved = resolveSide(side, rect, width, height, sideOffset);

    let left: number;
    let top: number;
    if (resolved === "bottom" || resolved === "top") {
      top =
        resolved === "bottom"
          ? rect.bottom + sideOffset
          : rect.top - sideOffset - height;
      left = alignOn(align, rect.left, rect.width, width);
    } else {
      left =
        resolved === "right"
          ? rect.right + sideOffset
          : rect.left - sideOffset - width;
      top = alignOn(align, rect.top, rect.height, height);
    }

    const [slideX, slideY] = SLIDE[resolved];
    content.style.left = `${fit(left, width, window.innerWidth)}px`;
    content.style.top = `${fit(top, height, window.innerHeight)}px`;
    content.style.setProperty("--ext-slide-x", slideX);
    content.style.setProperty("--ext-slide-y", slideY);
    content.dataset.side = resolved;
  }, [align, close, side, sideOffset]);

  useLayoutEffect(() => {
    if (!open) {
      return;
    }
    applyPosition();
    let frame: number;
    const follow = () => {
      applyPosition();
      frame = requestAnimationFrame(follow);
    };
    frame = requestAnimationFrame(follow);
    return () => {
      cancelAnimationFrame(frame);
    };
  }, [applyPosition, open]);

  useEffect(() => {
    if (!open) {
      return;
    }
    const handlePointerDown = (e: PointerEvent) => {
      const target = e.target as HTMLElement | null;
      if (
        target &&
        (triggerRef.current?.contains(target) ||
          contentRef.current?.contains(target))
      ) {
        return;
      }
      close();
    };
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        close();
      }
    };
    document.addEventListener("pointerdown", handlePointerDown, true);
    document.addEventListener("keydown", handleKeyDown, true);
    return () => {
      document.removeEventListener("pointerdown", handlePointerDown, true);
      document.removeEventListener("keydown", handleKeyDown, true);
    };
  }, [close, open]);

  const content = (children: ReactNode): null | ReactPortal =>
    open
      ? createPortal(
          <div
            ref={contentRef}
            data-ext-floating
            style={{ position: "fixed", zIndex: 60 } as CSSProperties}
          >
            {children}
          </div>,
          document.body
        )
      : null;

  return { content, triggerRef };
};

